class Solution {
public:
    string minWindow(string s, string t) {
        int m = t.size();
        vector<int> start(m, -1);
        int bestStart = -1;
        int bestLength = INT_MAX;
        for (int i = 0; i < static_cast<int>(s.size()); ++i) {
            for (int j = m - 1; j >= 0; --j) {
                if (s[i] != t[j]) {
                    continue;
                }
                if (j == 0) {
                    start[j] = i;
                } else if (start[j - 1] != -1) {
                    start[j] = start[j - 1];
                }
            }
            if (m > 0 && start[m - 1] != -1) {
                int len = i - start[m - 1] + 1;
                if (len < bestLength) {
                    bestLength = len;
                    bestStart = start[m - 1];
                }
            }
        }
        return bestStart == -1 ? "" : s.substr(bestStart, bestLength);
    }
};
